support='''(()=>{'use strict';const L=window.LESSON,host=document.querySelector('#activity');
function draw(){const state=window.LessonEngine?.state();if(state?.position.view!=='task')return;const id=state.position.task;const t=L.tasks[id];if(!t?.tableRows||host.querySelector('.summary-form'))return;
const table=document.createElement('table');table.className='summary-form';const head=document.createElement('thead'),hr=document.createElement('tr');['说明对象','事物的特点','对特点的说明','说明方法'].forEach(v=>{const th=document.createElement('th');th.textContent=v;hr.append(th)});head.append(hr);table.append(head);const body=document.createElement('tbody');
for(const r of t.tableRows){const tr=document.createElement('tr'),th=document.createElement('th');th.scope='row';th.textContent=r.name;tr.append(th);r.fields.forEach((id,i)=>{const input=host.querySelector('#field-'+id);if(!input)return;host.querySelector('label[for="field-'+id+'"]')?.remove();const td=document.createElement('td');td.dataset.label=['事物的特点','对特点的说明','说明方法'][i];td.append(input);tr.append(td)});body.append(tr)}table.append(body);host.insertBefore(table,host.querySelector('.actions'));}
new MutationObserver(draw).observe(host,{childList:true});draw();})();'''
(D/'lesson-support.js').write_text(support)
def page(title,body,extra='',cls=''):
 return f'''<!doctype html><html lang="zh-SG"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{e(title)} · 华文通</title><link rel="stylesheet" href="{S}style.css?v={V}"><link rel="stylesheet" href="lesson.css?v={V}"></head><body class="{cls}"><header class="site-header"><a href="../../../../../index.html#1/texts"><img src="../../../../../assets/huawentong-logo.png" alt="华文通"></a><span>{L['label']}</span></header><nav class="nav"><a class="btn" href="index.html">课文主页</a><a class="btn" href="reading.html">互动学习</a><a class="btn" href="comics.html">漫画回读</a><a class="btn" href="teacher.html">教师资料</a></nav><main>{body}</main>{extra}</body></html>'''
home='''<section class="hero"><div><p class="eyebrow">中一高级华文 · 单元三 · 巩固</p><h1>国家美术馆探秘</h1><p class="lead">读懂数字和例子，发现建筑与画作里的“秘密”。</p><a class="btn primary" href="reading.html">开始／继续学习</a><p class="intro-note">1—2课时 · 8段图文 · 个人词语本</p></div><div class="panel panel-direct"><img src="assets/panel-01.png" width="530" height="370" alt="原有漫画：国家美术馆外观"></div></section><section class="resource-grid"><a class="paper" href="reading.html#lesson1"><h2>第一课</h2><p>第1—7段<br>数字、建筑与钱包里的名作</p></a><a class="paper" href="reading.html#lesson2"><h2>第二课</h2><p>第8段与全文<br>开放回应、统整、仿写与查找</p></a><a class="paper" href="reading.html#words"><h2>我的词语本</h2><p>收藏词语<br>中英文释义与闪卡</p></a></section><p><a class="btn" href="teacher.html">教师资料与整套下载</a> <a class="btn" href="slides.html">在线投影</a></p>'''
(D/'index.html').write_text(page(L['title'],home))
comics='<h1>国家美术馆探秘</h1><p class="source-note">按段回读课文与原有漫画。数字以课文为准；画作与颜色变化图为示意。</p>'
cn='一二三四五六七八'
for i,p in enumerate(L['paragraphs']):
 comics+=f'<section class="paper reread"><h2>第{cn[i]}段</h2><p class="source-text">{e(p)}</p><div class="panel-list">'+''.join(f'<div class="panel panel-direct"><img loading="lazy" src="{L["panelImages"][n-1]}" alt="原有漫画第{n}格"></div>' for n in L['panels'][i])+'</div></section>'
comics+='<details><summary>查看四页完整原漫画</summary>'+''.join(f'<figure class="whole-comic"><img loading="lazy" src="assets/comic{i}.png" alt="完整原漫画第{i}页"></figure>' for i in range(1,5))+'</details>'
(D/'comics.html').write_text(page('漫画回读',comics))
teacher='''<h1>国家美术馆探秘 教师资料</h1><p>用数字和例子说明特点，用原文支持解释。先逐段读懂，再进行全文统整与开放回应。</p><section class="paper"><h2>资源</h2><div class="actions"><a class="btn primary" href="slides.html">在线投影</a><a class="btn" href="downloads/gallery-lesson.pptx" download>可编辑PPT</a><a class="btn" href="downloads/gallery-teacher.docx" download>教师流程与参考答案</a><button id="downloadOffline">下载离线学习页</button><button id="downloadPack">下载完整教学配套</button></div><p id="packStatus" role="status"></p></section><section class="paper"><h2>课堂安排</h2><p><b>两课时建议：</b>第一课50分钟，短导入3分钟，第1—2段10分钟，第3—6段18分钟，第7段书面回答及讲评14分钟，订正与词语整理5分钟。第二课50分钟，回顾4分钟，第8段及开放回应14分钟，全文统整12分钟，仿写与资料查找15分钟，检查与订正5分钟。</p><p><b>一课时紧凑版：</b>50分钟。导入2分钟，图文自读10分钟，按段核对重点12分钟，统整6分钟，仿句与查找8分钟，必做开放回应8分钟，检查4分钟。口头完成重复的事实小题，第7段答案可先口述；保留开放题书写与完整课本练习。程度较弱班级宜分两课。</p><p><b>目标：</b>准确解释五个“秘密”；把数字／例子与对应特点连起来；解释“既熟悉又陌生”并仿写；以具体内容支持个人选择。</p></section>'''
teacher+='<section class="paper"><h2>段落与漫画对应</h2><table><thead><tr><th>段号</th><th>内容与能力</th><th>原漫画格号</th></tr></thead><tbody>'+''.join(f'<tr><td>第{i+1}段</td><td>{e(L["paragraphIdeas"][i])}</td><td>{"、".join(map(str,L["panels"][i]))}</td></tr>' for i in range(8))+'</tbody></table></section>'
for t in L['tasks']:
 teacher+=f'<section class="paper answer-section"><h2>{e(t["title"])}</h2><p class="source-note">{e(t["source"])} · {e(t["role"])}</p>'+''.join('<p class="question">'+e(q)+'</p>' for q in t['questions'])+f'<h3>参考与取证</h3><p class="model">{e(t["answer"])}</p><p>{e(t["explain"])}</p><h3>评分与误区</h3><p>{e(t["scoreGuide"])}</p><p>{e(t["reject"])}</p><h3>分层提示</h3><p>{e(t["hints"][0])}<br>{e(t["hints"][1])}</p>'
 if t.get('oral'):teacher+='<h3>口头追问</h3>'+''.join('<p><b>'+e(q)+'</b><br>'+e(a)+'</p>' for q,a in t['oral'])
 teacher+='</section>'
teacher+='''<section class="paper"><h2>资料边界与课堂记录</h2><p>原文逐段保留附件。6万4000平方米、9000余件等按课文教学，不用作今日馆藏查询。漫画画作是情境示意，不代替原画；第20格的颜色变化不能证明课文未写的原色。</p><p>教材与原漫画用“钟泗滨”。部分官方资料写作“钟泗宾”，英文同为Cheong Soo Pieng；本配套保留教材写法。查找题答案为陈文希的Two Gibbons Amidst Vines；MAS简称Gibbon。</p><p>普通学习链接在本机保存姓名、班级、学号、首次作答与订正，可导出JSON、CSV及文字记录。词语本跨同域课文保存；清除浏览器数据前先备份。开放题、仿句与解释题由教师覆核，自检不等于评分。</p><p>如从教学管理助手建立班级任务并发放学生专属链接，使用该任务的收件功能。普通公共链接不自动交给老师。离线页只本机保存，查找资料链接需要网络。</p><p><a class="btn" href="../../../../../bei/management/textbook/?lesson=s1u3l3">课堂教学进度</a></p><h3>查找题资料</h3><p>核对日期：2026年10月23日。<a href="https://www.mas.gov.sg/currency/circulation-currency/circulation-currency-notes" target="_blank" rel="noopener">新加坡金融管理局：Portrait Series $50</a>；<a href="https://www.nationalgallery.sg/content/dam/about/annual-reports/reports/FY2016%20Annual%20Report.pdf#page=19" target="_blank" rel="noopener">国家美术馆2016年度报告，印刷页16（PDF第19页）</a>；<a href="https://iseaa.nafa.edu.sg/resources/collections/artist/cheong-soo-pieng" target="_blank" rel="noopener">南艺：Cheong Soo Pieng</a>。</p></section>'''
(D/'teacher.html').write_text(page('教师流程与参考答案',teacher,f'<script src="{S}package-v2.js?v={V}"></script>','teacher-page'))
projector='''<h1>国家美术馆探秘</h1><div class="actions"><button id="prev">上一页</button><select id="slideSelect" aria-label="选择投影片"></select><button id="next">下一页</button><button id="fullscreen">全屏</button></div><p id="counter"></p><div id="projector"><img id="slideImage" alt="当前投影片"></div><details><summary>教师备注</summary><p id="notes"></p></details>'''
pj='''<script src="slides-data.js"></script><script>(()=>{const D=window.SLIDES,$=id=>document.getElementById(id);let i=Math.max(0,Math.min(D.length-1,Number(location.hash.slice(1)||1)-1));$('slideSelect').innerHTML=D.map((s,n)=>'<option value="'+n+'">'+(n+1)+' · '+s.title+'</option>').join('');function draw(){const s=D[i];$('slideImage').src='slides/slide-'+String(i+1).padStart(2,'0')+'.png';$('slideImage').alt=s.title;$('slideSelect').value=i;$('counter').textContent=(i+1)+' / '+D.length;$('notes').textContent=s.notes;$('prev').disabled=i===0;$('next').disabled=i===D.length-1;history.replaceState(null,'','#'+(i+1))}$('prev').onclick=()=>{if(i)i--;draw()};$('next').onclick=()=>{if(i<D.length-1)i++;draw()};$('slideSelect').onchange=e=>{i=+e.target.value;draw()};$('fullscreen').onclick=()=>$('projector').requestFullscreen?.();document.addEventListener('keydown',e=>{if(e.target.matches('select,input,textarea'))return;if(e.key==='ArrowRight')$('next').click();if(e.key==='ArrowLeft')$('prev').click()});draw()})()</script>'''
(D/'slides.html').write_text(page('在线投影',projector,pj))
readme='''国家美术馆探秘 完整教学配套\n中一高级华文 第三单元 巩固课文 1—2课时\n\n1. 在线学习：打开index.html或正式课文入口。\n2. 无网络课堂：打开“国家美术馆探秘_离线学习.html”，逐段漫画、词语释义、闪卡及作答可用。\n3. 教师资料：downloads/gallery-lesson.pptx为可编辑PPT，downloads/gallery-teacher.docx为教案与答案。\n4. slides.html为在线投影，slides内的图片与PPT顺序一致。\n5. assets/comic1—4.png为四页原漫画；panel-01—32.png是按原格框无损提取的显示副本。\n6. 检查页可导出学习记录；主观题由教师覆核。离线使用关闭前请导出备份。\n7. 查找题的网络资料需要联网；无网络时教师可用手册中的核对结果讲评。\n'''
(D/'使用说明.txt').write_text(readme)
print('Built reading, home, comics, teacher, projector and instructions')
